def find_duplicates(roman_or_int):
    """Convert between Roman numerals and integers.

    Accepts either a string (Roman numeral -> int) or an int (-> Roman numeral).
    Raises ValueError for invalid input or out-of-range values (1-3999).
    """
    if isinstance(roman_or_int, str):
        return _roman_to_int(roman_or_int.upper())
    elif isinstance(roman_or_int, int):
        return _int_to_roman(roman_or_int)
    else:
        raise TypeError(f"Expected str or int, got {type(roman_or_int).__name__}")


_ROMAN_VALUES = {
    'I': 1, 'V': 5, 'X': 10, 'L': 50,
    'C': 100, 'D': 500, 'M': 1000,
}

_INT_TO_ROMAN = [
    (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
    (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
    (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I'),
]


def _roman_to_int(s):
    if not s or not isinstance(s, str):
        raise ValueError("Input must be a non-empty string")
    for ch in s:
        if ch not in _ROMAN_VALUES:
            raise ValueError(f"Invalid Roman numeral character: {ch}")
    result = 0
    i = 0
    while i < len(s):
        # If current value is less than next value, it's a subtractive pair
        if i + 1 < len(s) and _ROMAN_VALUES[s[i]] < _ROMAN_VALUES[s[i + 1]]:
            result += _ROMAN_VALUES[s[i + 1]] - _ROMAN_VALUES[s[i]]
            i += 2
        else:
            result += _ROMAN_VALUES[s[i]]
            i += 1
    # Validate the result round-trips correctly
    if _int_to_roman(result) != s:
        raise ValueError(f"Invalid Roman numeral: {s}")
    return result


def _int_to_roman(n):
    if not isinstance(n, int):
        raise TypeError(f"Expected int, got {type(n).__name__}")
    if n < 1 or n > 3999:
        raise ValueError(f"Value must be between 1 and 3999, got {n}")
    result = []
    for value, numeral in _INT_TO_ROMAN:
        while n >= value:
            result.append(numeral)
            n -= value
    return ''.join(result)


# ── Tests ──────────────────────────────────────────────────────────────────────

def test_roman_to_int():
    cases = {
        'I': 1, 'II': 2, 'III': 3, 'IV': 4, 'V': 5,
        'VI': 6, 'VII': 7, 'VIII': 8, 'IX': 9, 'X': 10,
        'XI': 11, 'XIV': 14, 'XIX': 19, 'XX': 20, 'XL': 40,
        'XLII': 42, 'L': 50, 'XC': 90, 'XCIX': 99, 'C': 100,
        'CD': 400, 'D': 500, 'CM': 900, 'M': 1000,
        'MCMLXXXIV': 1984, 'MMXXVI': 2026, 'MMMCMXCIX': 3999,
        'mcmxcix': 1989,  # case insensitive
    }
    for roman, expected in cases.items():
        result = find_duplicates(roman)
        assert result == expected, f"{roman}: expected {expected}, got {result}"
    print(f"PASS: roman_to_int ({len(cases)} cases)")


def test_int_to_roman():
    cases = {
        1: 'I', 4: 'IV', 9: 'IX', 14: 'XIV', 40: 'XL',
        42: 'XLII', 90: 'XC', 99: 'XCIX', 400: 'CD',
        900: 'CM', 1984: 'MCMLXXXIV', 2026: 'MMXXVI',
        3999: 'MMMCMXCIX',
    }
    for n, expected in cases.items():
        result = find_duplicates(n)
        assert result == expected, f"{n}: expected {expected}, got {result}"
    print(f"PASS: int_to_roman ({len(cases)} cases)")


def test_roundtrip():
    for n in range(1, 4000):
        roman = find_duplicates(n)
        back = find_duplicates(roman)
        assert back == n, f"Roundtrip failed for {n}: {roman} -> {back}"
    print("PASS: roundtrip (1-3999)")


def test_invalid_input():
    import pytest
    # Invalid Roman characters
    for bad in ['A', 'IIII', 'VV', 'IC', 'XM', '']:
        with pytest.raises(ValueError):
            find_duplicates(bad)
    # Out-of-range integers
    for bad in [0, -1, 4000, 10000]:
        with pytest.raises(ValueError):
            find_duplicates(bad)
    # Wrong type
    with pytest.raises(TypeError):
        find_duplicates(3.14)
    print("PASS: invalid_input")


if __name__ == '__main__':
    test_roman_to_int()
    test_int_to_roman()
    test_roundtrip()
    test_invalid_input()
    print("\nAll tests passed.")
